    def is_cube(n: int) -> bool:
        if n == 0:
            return True
        abs_n = abs(n)
        cube_root = round(abs_n ** (1/3))
        return cube_root ** 3 == abs_n

    def is_square(n: int) -> bool:
        if n < 0:
            return False
        root = round(n ** 0.5)
        return root * root == n

    if not (is_cube(a) and is_cube(b) and is_cube(c)):
        return False

